mapper.select:
SELECT b.board_id AS boardId, b.category, b.title, b.views, b.likes, b.is_pinned AS isPinned, b.created_at AS createdAt, m.name AS authorName, (SELECT COUNT(*) FROM BOARD_COMMENT WHERE board_id = b.board_id) AS commentsCount FROM BOARD b JOIN MEMBER m ON b.author_id = m.member_id
b.category = #{category}
ORDER BY b.is_pinned DESC, b.created_at DESC, b.board_id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM BOARD_LIKE
WHERE board_id = #{boardId} AND member_id = #{memberId}

mapper.update:
UPDATE BOARD
SET likes = likes + #{amount}
WHERE board_id = #{boardId}
